    args = parser.parse_args()
    _ = json.loads(args.payload)  # unused
    customers = {}
    with open('/inputs/customers.csv', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            customers[row['customer_id']] = row['region']
    total = 0.0
