import argparse
import json
import csv
import re

def find_amount_column(rows):
    if len(rows) < 2:
        return None
    header = rows[0]
    data = rows[1:]
    col_counts = [0] * len(header)
    for row in data:
        if not any(cell.strip() for cell in row):
            continue
        for i, cell in enumerate(row):
            if i >= len(header):
                continue
            stripped = cell.strip()
            if not stripped:
                continue
            cleaned = stripped.replace('$', '').replace(',', '')
            try:
                float(cleaned)
                col_counts[i] += 1
            except ValueError:
                pass
    if max(col_counts) == 0:
        return None
    return col_counts.index(max(col_counts))

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('payload')
    args = parser.parse_args()
    params = json.loads(args.payload)
    filepath = params['path']
    with open(filepath, newline='') as f:
        reader = csv.reader(f)
        rows = list(reader)
    col_idx = find_amount_column(rows)
    total = 0.0
    if col_idx is not None:
        for row in rows[1:]:
            if not any(cell.strip() for cell in row):
                continue
            if col_idx < len(row):
                cell = row[col_idx].strip()
                if cell:
                    cleaned = cell.replace('$', '').replace(',', '')
                    try:
                        total += float(cleaned)
                    except ValueError:
                        pass
    print(f"{total:.2f}")

if __name__ == '__main__':
    main()

import argparse
import json


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    payload = json.loads(parser.parse_args().payload)
    path = payload["path"]

    user_max = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                continue

            user = obj.get("user")
            action = obj.get("action")
            ts = obj.get("ts")
            if user is None or action is None or ts is None:
                continue

            # Ties on max ts are resolved by the last line for that user.
            if user not in user_max or ts >= user_max[user][0]:
                user_max[user] = (ts, action)

    count = sum(1 for _, action in user_max.values() if action == "logout")
    print(count)


if __name__ == "__main__":
    main()

import argparse
import json
import csv
from datetime import datetime

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    config = json.loads(args.payload)
    path = config["path"]
    dates = []
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        if reader.fieldnames:
            date_col = None
            for col in reader.fieldnames:
                if col.lower() == 'date':
                    date_col = col
                    break
            if date_col is None:
                date_col = reader.fieldnames[0]
            for row in reader:
                date_str = row.get(date_col, '').strip()
                if date_str:
                    try:
                        dt = datetime.strptime(date_str, '%Y-%m-%d')
                        dates.append(dt)
                    except ValueError:
                        pass
    if not dates:
        print(0)
    else:
        earliest = min(dates)
        latest = max(dates)
        diff = (latest - earliest).days
        print(diff)

if __name__ == '__main__':
    main()

