import argparse, json, csv
from datetime import datetime

def main():
    p = argparse.ArgumentParser()
    p.add_argument('payload')
    args = json.loads(p.parse_args().payload)
    path = args['path']
    dates = []
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        date_col = None
        if reader.fieldnames:
            for name in reader.fieldnames:
                if name and name.strip().lower() == 'date':
                    date_col = name
                    break
        for row in reader:
            if date_col is None:
                continue
            raw = row.get(date_col)
            if raw is None:
                continue
            raw = raw.strip()
            if not raw:
                continue
            try:
                d = datetime.strptime(raw, '%Y-%m-%d').date()
            except ValueError:
                continue
            dates.append(d)
    if not dates:
        print(0)
    else:
        earliest = min(dates)
        latest = max(dates)
        print((latest - earliest).days)

if __name__ == '__main__':
    main()

import argparse
import json
import csv


def normalize(s):
    return s.strip().lower().replace(" ", "_").replace("-", "_")


def find_col(fieldnames, target):
    wanted = normalize(target)
    for name in fieldnames:
        if normalize(name) == wanted:
            return name
    return None


def parse_amount(s):
    if s is None:
        return 0.0
    s = s.strip()
    if not s:
        return 0.0
    s = s.replace("$", "").replace(",", "")
    return float(s)


def load_customers(path):
    customers = {}
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        if not reader.fieldnames:
            return customers
        cid_col = find_col(reader.fieldnames, "customer_id") or find_col(reader.fieldnames, "customer id")
        region_col = find_col(reader.fieldnames, "region")
        if not cid_col or not region_col:
            raise ValueError("customers.csv must contain customer_id and region columns")
        for row in reader:
            cid = row.get(cid_col, "").strip()
            region = row.get(region_col, "").strip()
            if cid:
                customers[cid] = region
    return customers


def load_orders(path):
    rows = []
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        if not reader.fieldnames:
            return rows
        cid_col = find_col(reader.fieldnames, "customer_id") or find_col(reader.fieldnames, "customer id")
        amount_col = find_col(reader.fieldnames, "order_amount") or find_col(reader.fieldnames, "amount")
        if not cid_col or not amount_col:
            raise ValueError("orders.csv must contain customer_id and amount columns")
        for row in reader:
            cid = row.get(cid_col, "").strip()
            if cid:
                rows.append((cid, parse_amount(row.get(amount_col, ""))))
    return rows


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    payload = json.loads(parser.parse_args().payload)
    customers_path = payload["customers"]
    orders_path = payload["orders"]
    customers = load_customers(customers_path)
    total = 0.0
    for cid, amount in load_orders(orders_path):
        if customers.get(cid, "").lower() == "west":
            total += amount
    if total.is_integer():
        print(int(total))
    else:
        print(total)


if __name__ == "__main__":
    main()

import csv
import argparse
import json

def parse_amount(s):
    s = s.strip().replace('$','').replace(',','')
    if s.startswith('(') and s.endswith(')'):
        s = '-' + s[1:-1]
    return float(s)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    params = json.loads(args.payload)
    filepath = params["path"]
    total = 0.0
    with open(filepath, 'r', newline='') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if header is None:
            print("0.00")
            return
        amount_idx = None
        for i, col in enumerate(header):
            if 'amount' in col.strip().lower():
                amount_idx = i
                break
        if amount_idx is None:
            if len(header) > 1:
                amount_idx = 1
            else:
                raise ValueError("No 'amount' column found.")
        for row in reader:
            if not row or all(cell.strip() == '' for cell in row):
                continue
            try:
                amount_str = row[amount_idx].strip()
                amount = parse_amount(amount_str)
                total += amount
            except (ValueError, IndexError):
                pass
    print(f"{total:.2f}")

if __name__ == "__main__":
    main()
